def save_state(st):
    for k in ("titles", "topics", "openers"):
        st[k] = st[k][-200:]
    st["done"] = dict(list(st["done"].items())[-60:])
    STATE_FILE.write_text(json.dumps(st, ensure_ascii=False, indent=1), "utf-8")


