def produce(kind, st, now_utc, wd, args):
    WORK.mkdir(exist_ok=True)
    OUT.mkdir(exist_ok=True)
    tmp = WORK / kind
    if tmp.exists():
        subprocess.run(["rm", "-rf", str(tmp)])
    (tmp / "frames").mkdir(parents=True)
    short = kind == "short"
    area = args.area or (LONG_SLOTS[wd][0] if wd in LONG_SLOTS else "math")
    log(f"=== {kind.upper()} | {now_utc:%Y-%m-%d} | area={area if not short else SHORT_FORMATS[wd][0]}")
    comments = [] if (args.dry_run and not os.getenv("YT_REFRESH_TOKEN")) or short else (fetch_comments() if os.getenv("YT_REFRESH_TOKEN") else [])
    script = gen_short(st, wd) if short else gen_long(st, area, comments)
    log(f"  title: {script['title']}")
    wav, tl = build_audio(script, tmp, short, tail=0.5 if short else 5.5)
    log(f"  voice done: {tl['total']:.1f}s")
    if short and tl["total"] > 59:
        log("  WARNING: short longer than 59s")
    mp4 = OUT / f"{kind}_{now_utc:%Y%m%d}.mp4"
    render_video(script, tl, wav, short, tmp / "frames", mp4)
    log(f"  video ready: {mp4} ({mp4.stat().st_size / 1e6:.1f} MB)")
    thumb = None
    if not short:
        thumb = OUT / f"thumb_{now_utc:%Y%m%d}.jpg"
        make_thumb(script["thumb_text"], script.get("area", area), thumb)
    desc = build_description(script, tl)
    title = re.sub(r"\s+", " ", script["title"]).strip()
    if args.dry_run:
        (OUT / f"{kind}_{now_utc:%Y%m%d}.json").write_text(json.dumps({"title": title, "description": desc, "tags": script["tags"]}, indent=1, ensure_ascii=False))
        log("  DRY RUN: not uploaded")
        return
    publish_at = None if args.publish_now else slot_time(now_utc, kind, wd)
    vid = yt_upload(mp4, title, desc, script["tags"], publish_at)
    if thumb:
        yt_thumb(vid, thumb)
    log(f"  UPLOADED https://youtu.be/{vid}  " + (f"scheduled {publish_at:%Y-%m-%d %H:%M} UTC (= {publish_at.astimezone(KSA):%H:%M} KSA)" if publish_at else "published now"))
    st["titles"].append(title)
    st["topics"].append(script["topic"])
    st["openers"].append(script.get("opener", ""))
    if not short:
        sidx = script.get("series_idx")
        if sidx:
            st["series"] = [x for x in st["series"] if x is not sidx]
            if sidx["next"] < sidx["total"]:
                sidx["next"] += 1
                st["series"].append(sidx)
        elif script.get("parts_total", 1) > 1:
            st["series"].append({"area": area, "topic": script["topic"], "next": 2, "total": script["parts_total"]})
    st["done"].setdefault(f"{now_utc:%Y-%m-%d}", []).append(kind)
    save_state(st)


def selftest(which):
    os.environ["FAKE_TTS"] = "1"
    short = which == "short"
    WORK.mkdir(exist_ok=True)
    OUT.mkdir(exist_ok=True)
    tmp = WORK / "selftest"
    subprocess.run(["rm", "-rf", str(tmp)])
    (tmp / "frames").mkdir(parents=True)
    wav, tl = build_audio(SAMPLE, tmp, short, tail=0.5 if short else 5.5)
    out = OUT / f"selftest_{which}.mp4"
    render_video(SAMPLE, tl, wav, short, tmp / "frames", out)
    make_thumb(SAMPLE["thumb_text"], "math", OUT / "selftest_thumb.jpg")
    log("selftest OK:", out, f"{tl['total']:.1f}s")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--selftest", choices=["short", "long"])
    ap.add_argument("--mode", default=os.getenv("MODE") or "auto", choices=["auto", "long", "short", "both"])
    ap.add_argument("--area", default=os.getenv("AREA") or "")
    ap.add_argument("--publish-now", action="store_true", default=flag("PUBLISH_NOW"))
    ap.add_argument("--dry-run", action="store_true", default=flag("DRY_RUN"))
    ap.add_argument("--force", action="store_true", default=flag("FORCE"))
    args = ap.parse_args()
    if args.selftest:
        return selftest(args.selftest)
    st = load_state()
    now = datetime.now(timezone.utc)
    wd = now.weekday()
    if args.mode == "auto":
        kinds = (["long"] if wd in LONG_SLOTS else []) + ["short"]
    elif args.mode == "both":
        kinds = ["long", "short"]
    else:
        kinds = [args.mode]
    failed = []
    for kind in kinds:
        if kind in st["done"].get(f"{now:%Y-%m-%d}", []) and not (args.force or args.dry_run):
            log(f"skip {kind}: already published today (use force to redo)")
            continue
        try:
            produce(kind, st, now, wd, args)
        except Exception:
            traceback.print_exc()
            failed.append(kind)
    if failed:
        sys.exit(1)


if __name__ == "__main__":
    main()
